package com.kotoba.window;
import android.content.*;import android.media.*;import android.os.*;import com.k2fsa.sherpa.onnx.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
final class Voice {
 static Voice instance; final Context context; final ExecutorService worker=Executors.newSingleThreadExecutor(); final Handler handler=new Handler(Looper.getMainLooper());final AtomicInteger generation=new AtomicInteger();OfflineTts engine;MediaPlayer player;AudioManager manager;AudioFocusRequest focus;
 interface Status{void show(String s);}
 static synchronized Voice get(Context c){if(instance==null)instance=new Voice(c.getApplicationContext());return instance;}Voice(Context c){context=c;manager=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);}
 void stop(){generation.incrementAndGet();if(player!=null){try{player.stop();}catch(Exception e){}player.release();player=null;}if(focus!=null){manager.abandonAudioFocusRequest(focus);focus=null;}}
 void speak(String text,String id,Status status){stop();int version=generation.get();status.show("离线语音正在准备…");worker.execute(()->{if(version!=generation.get())return;try{File cache=new File(context.getCacheDir(),"speech");cache.mkdirs();File wav=new File(cache,Integer.toHexString((id+text).hashCode())+".wav");if(!wav.exists()){if(engine==null){OfflineTtsSupertonicModelConfig m=new OfflineTtsSupertonicModelConfig();m.setDurationPredictor("model/duration_predictor.int8.onnx");m.setTextEncoder("model/text_encoder.int8.onnx");m.setVectorEstimator("model/vector_estimator.int8.onnx");m.setVocoder("model/vocoder.int8.onnx");m.setTtsJson("model/tts.json");m.setUnicodeIndexer("model/unicode_indexer.bin");m.setVoiceStyle("model/voice.bin");OfflineTtsModelConfig model=new OfflineTtsModelConfig();model.setSupertonic(m);model.setNumThreads(2);model.setProvider("cpu");OfflineTtsConfig config=new OfflineTtsConfig();config.setModel(model);config.setMaxNumSentences(1);config.setSilenceScale(.2f);engine=new OfflineTts(context.getAssets(),config);}if(version!=generation.get())return;GenerationConfig g=new GenerationConfig();g.setSid(0);g.setSpeed(.95f);g.setSilenceScale(.2f);g.setNumSteps(8);g.setExtra(Collections.singletonMap("lang","ja"));GeneratedAudio audio=engine.generateWithConfig(text.replace("〜","").replace("～",""),g);if(audio.getSamples().length==0||!audio.save(wav.getAbsolutePath()))throw new IOException("未生成音频");trim(cache,wav);}handler.post(()->{if(version!=generation.get())return;try{AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK).setAudioAttributes(attrs).setOnAudioFocusChangeListener(change->{if(change<0)stop();}).build();if(manager.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){status.show("其他应用正在使用音频，请稍后重试");return;}player=new MediaPlayer();player.setAudioAttributes(attrs);player.setDataSource(wav.getAbsolutePath());player.setOnCompletionListener(mp->stop());player.prepare();player.start();status.show("Supertonic · 离线日语");}catch(Exception e){stop();status.show("播放失败："+e.getMessage());}});}catch(Throwable e){handler.post(()->{if(version==generation.get())status.show("离线发音失败："+e.getMessage());});}});}
 void trim(File dir,File keep){File[] files=dir.listFiles();if(files==null)return;long size=0;for(File f:files)size+=f.length();if(size<100*1024*1024)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));for(File f:files){if(size<80*1024*1024)break;if(!f.equals(keep)){long n=f.length();if(f.delete())size-=n;}}}
}